    public void MoveNext() { /* switch (state) … — см. стенд */ }
}

// что примерно сгенерировал компилятор для SumAsync (упрощённо)
Task<int> SumAsync()
{
    var sm = new SumAsyncStateMachine();
    sm.builder = AsyncTaskMethodBuilder<int>.Create();
    sm.state = -1;
    sm.builder.Start(ref sm);   // первый MoveNext — синхронно, в вызывающем потоке
    return sm.builder.Task;     // вызывающий получает задачу
}

